/// <summary>
/// Data contract class for service <C>METSendSalesOrderInvoiceBusinessEventService</C>
/// </summary>
[DataContractAttribute,
SysOperationContractProcessingAttribute(classStr(METSendSalesOrderInvoiceBusinessEventUIBuilder))]
public class METSendSalesOrderInvoiceBusinessEventContract implements SysOperationValidatable
{
    private METIndustryKey  industryKey;

}

Method.Source:
/// <summary>
/// parm method for industry key
/// </summary>
/// <param name = "_industryKey">Industry key value</param>
/// <returns>Industry key</returns>
[DataMemberAttribute("@MET:IndustryKey")]
public METIndustryKey parmIndustryKey(METIndustryKey _industryKey = industryKey)
{
    industryKey = _industryKey;
    return industryKey;
}

    /// <summary>
    ///    Validates the parameters.
    /// </summary>
    /// <returns>
    ///    true if no errors; otherwise, false.
    /// </returns>
    [Hookable(false)]
    public boolean validate()
    {
        boolean isValid = true;
        METIndustryKeyTable  metIndustryKeyTable;

        if(industryKey)
        {
            select firstonly IndustryKey from metIndustryKeyTable where metIndustryKeyTable.IndustryKey == industryKey;
            if (!metIndustryKeyTable)
            {
                isValid = checkFailed("@MET:IndustryKeyValidation");
            }
        }

        return isValid;
    }
